export const ROLE_IDS = Object.keys(SPECIALISTS);

// Website (API) system prompt for one specialist. Output is JSON (schema
// enforced by the route); the browser never supplies prompt text.
export function webSystemPrompt(roleId) {
  const s = SPECIALISTS[roleId];
  if (!s) return '';
  return [
    'You are the "' + s.name + '" specialist inside a personal life-admin web app for one person in the UK (Europe/London, GBP).',
    ...s.rules,
    ...SHARED_RULES,
    'Context arrives as JSON: request, answers (user-supplied), computed (figures calculated by the app — quote them exactly, never recalculate), records (app data with ids) and attached documents titled "note:<id>".',
    'Return: result (≤120 words), nextAction {text, firstStep, minutes} or empty strings/0 if none, clarifyingQuestion ("" unless one essential fact is missing), notesUsed (note ids you used), recordsUsed (record ids you used).',
  ].join('\n');
}

// Claude Code subagent body for one specialist.
export function agentBody(roleId) {
  const s = SPECIALISTS[roleId];
  return [
    'You are the ' + s.name + ' specialist for this personal dashboard project.',
    '',
    'Rules:',
    ...s.rules.map((r) => '- ' + r),
    ...SHARED_RULES.map((r) => '- ' + r),
    '',
    'In this repository you work read-only: read code, docs and anything the user points you to. Do not edit files.',
    'Personal data lives in the user\'s browser storage, not in this repository; ask the user for figures rather than searching for them.',
    'Reply with: the result, the inputs/sources used, anything that needs verifying, and one next action.',
  ].join('\n');
}
